class Solution:
    def rotateNonNegativeElements(self, nums: List[int], k: int) -> List[int]:
        idx = [i for i, x in enumerate(nums) if x >= 0]
        vals = [nums[i] for i in idx]
        m = len(vals)
        if m:
            k %= m
            vals = vals[k:] + vals[:k]
            for p, i in enumerate(idx):
                nums[i] = vals[p]
        return nums

