class Solution {
public:
    vector<int> rotateNonNegativeElements(vector<int>& nums, int k) {
        vector<int> idx, vals;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i] >= 0) { idx.push_back(i); vals.push_back(nums[i]); }
        int m = vals.size();
        if (m) {
            k %= m;
            vector<int> rot(vals.begin() + k, vals.end());
            rot.insert(rot.end(), vals.begin(), vals.begin() + k);
            for (int p = 0; p < m; p++) nums[idx[p]] = rot[p];
        }
        return nums;
    }
};

