class Solution {
    public int[] rotateNonNegativeElements(int[] nums, int k) {
        List<Integer> idx = new ArrayList<>();
        List<Integer> vals = new ArrayList<>();
        for (int i = 0; i < nums.length; i++)
            if (nums[i] >= 0) { idx.add(i); vals.add(nums[i]); }
        int m = vals.size();
        if (m > 0) {
            k %= m;
            Integer[] rot = new Integer[m];
            for (int p = 0; p < m; p++) rot[p] = vals.get((p + k) % m);
            for (int p = 0; p < m; p++) nums[idx.get(p)] = rot[p];
        }
        return nums;
    }
}

