from collections import deque
class Solution:
    def rotateNonNegativeElements(self, nums: List[int], k: int) -> List[int]:
        idx = [i for i, x in enumerate(nums) if x >= 0]
        dq = deque(x for x in nums if x >= 0)
        if dq:
            dq.rotate(-k)
            for i in idx:
                nums[i] = dq.popleft()
        return nums

