    vector<int> rotateNonNegativeElements(vector<int>& nums, int k) {
        vector<int> idx;
        deque<int> dq;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i] >= 0) { idx.push_back(i); dq.push_back(nums[i]); }
        if (!dq.empty()) {
            int m = dq.size(); k %= m;
            while (k--) { dq.push_back(dq.front()); dq.pop_front(); }
            for (int i : idx) { nums[i] = dq.front(); dq.pop_front(); }
        }
        return nums;
    }
};

