import java.util.*;
class Solution {
    public int[] rotateNonNegativeElements(int[] nums, int k) {
        List<Integer> idx = new ArrayList<>();
        ArrayDeque<Integer> dq = new ArrayDeque<>();
        for (int i = 0; i < nums.length; i++)
            if (nums[i] >= 0) { idx.add(i); dq.addLast(nums[i]); }
        if (!dq.isEmpty()) {
            int m = dq.size(); k %= m;
            while (k-- > 0) dq.addLast(dq.pollFirst());
            for (int i : idx) nums[i] = dq.pollFirst();
        }
        return nums;
    }
}

